<?php
declare(strict_types=1);require_once __DIR__.'/includes/admin_auth.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('shipping_rates.php');verify_csrf();$id=filter_input(INPUT_POST,'rate_id',FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');if(!$id||!in_array($action,['toggle','delete'],true)){flash('warning','Tindakan tarif tidak valid.');redirect('shipping_rates.php');}if($action==='toggle'){$pdo->prepare('UPDATE shipping_rates SET is_active=IF(is_active=1,0,1),updated_at=NOW() WHERE id=:id')->execute(['id'=>$id]);$message='Status tarif berhasil diubah.';}else{$pdo->prepare('DELETE FROM shipping_rates WHERE id=:id')->execute(['id'=>$id]);$message='Tarif berhasil dihapus.';}log_admin_activity($pdo,'shipping_rate_'.$action,'Mengelola tarif pengiriman #'.$id);flash('success',$message);redirect('shipping_rates.php');
